#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime
import re, subprocess, tempfile
path=Path('index.html')
if not path.is_file(): raise SystemExit('STOP: index.html not found. Run from repository root.')
s=path.read_text(encoding='utf-8')
old="/* Ratings-based annual award, with a separate top scorer. Existing awards remain intact. */\ntlPickPlayerOfYear=function(){\n squadLoad();const data=tlReadRecords(),ratings=data.ratings||{};\n return [...squadPlayers].filter(p=>(p.seasonApps||0)>0).sort((a,b)=>{\n  const ar=ratings[String(a.id)+'|'+a.name],br=ratings[String(b.id)+'|'+b.name];\n  const av=ar?.apps?ar.total/ar.apps:6,bv=br?.apps?br.total/br.apps:6;\n  return (bv+Math.min(1,(b.seasonApps||0)/20))-(av+Math.min(1,(a.seasonApps||0)/20))||b.rating-a.rating;\n })[0]||null;\n};\nconst tlRatingsRecordAward=tlRecordAward;\ntlRecordAward=function(){\n const year=seasonLabel(),awards=tlAwardHistory();if(awards[year])return awards[year];\n const data=tlReadRecords(),ratings=data.ratings||{};squadLoad();const players=squadPlayers.filter(p=>(p.seasonApps||0)>0);if(!players.length)return tlRatingsRecordAward();\n const winner=[...players].sort((a,b)=>{const ar=ratings[String(a.id)+'|'+a.name],br=ratings[String(b.id)+'|'+b.name];const av=ar?.apps?ar.total/ar.apps:6,bv=br?.apps?br.total/br.apps:6;return bv-av||b.seasonApps-a.seasonApps})[0];\n const scorer=[...players].sort((a,b)=>(b.seasonGoals||0)-(a.seasonGoals||0)||b.seasonApps-a.seasonApps)[0];\n const row=ratings[String(winner.id)+'|'+winner.name];const award={name:winner.name,goals:winner.seasonGoals||0,appearances:winner.seasonApps||0,rating:row?.apps?Number((row.total/row.apps).toFixed(2)):null,topScorer:scorer.name,topGoals:scorer.seasonGoals||0};\n awards[year]=award;localStorage.setItem(tlAwardKey(),JSON.stringify(awards));return award;\n};\n"
new="/* Annual award: sustained performances across league and cup matches. */\nfunction tlAwardEligiblePlayers(players,data){\n const season=seasonLabel();\n const matches=(data.matches||[]).filter(m=>m.season===season);\n // League has 22 fixtures; cup fixtures increase the participation threshold.\n const fixtureCount=Math.max(22,new Set(matches.map(m=>m.id)).size);\n const minimum=Math.ceil(fixtureCount*.70);\n const eligible=players.filter(p=>(p.seasonApps||0)>=minimum);\n // If unusual squad turnover leaves nobody eligible, use the most-used players.\n if(eligible.length)return eligible;\n const most=Math.max(0,...players.map(p=>p.seasonApps||0));\n return players.filter(p=>most>0&&(p.seasonApps||0)===most);\n}\nfunction tlAwardAverage(p,ratings){\n const row=ratings[String(p.id)+'|'+p.name];\n return row?.apps?row.total/row.apps:6;\n}\ntlPickPlayerOfYear=function(){\n squadLoad();const data=tlReadRecords(),ratings=data.ratings||{};\n return tlAwardEligiblePlayers(squadPlayers,data).sort((a,b)=>\n  tlAwardAverage(b,ratings)-tlAwardAverage(a,ratings)||\n  (b.seasonGoals||0)-(a.seasonGoals||0)||\n  (b.seasonApps||0)-(a.seasonApps||0)||b.rating-a.rating)[0]||null;\n};\nconst tlRatingsRecordAward=tlRecordAward;\ntlRecordAward=function(){\n const year=seasonLabel(),awards=tlAwardHistory();if(awards[year])return awards[year];\n const data=tlReadRecords(),ratings=data.ratings||{};squadLoad();\n const players=squadPlayers.filter(p=>(p.seasonApps||0)>0);\n if(!players.length)return tlRatingsRecordAward();\n const winner=tlAwardEligiblePlayers(players,data).sort((a,b)=>\n  tlAwardAverage(b,ratings)-tlAwardAverage(a,ratings)||\n  (b.seasonGoals||0)-(a.seasonGoals||0)||\n  (b.seasonApps||0)-(a.seasonApps||0)||b.rating-a.rating)[0];\n const scorer=[...players].sort((a,b)=>(b.seasonGoals||0)-(a.seasonGoals||0)||b.seasonApps-a.seasonApps)[0];\n const row=ratings[String(winner.id)+'|'+winner.name];\n const award={name:winner.name,goals:winner.seasonGoals||0,appearances:winner.seasonApps||0,rating:row?.apps?Number((row.total/row.apps).toFixed(2)):null,topScorer:scorer.name,topGoals:scorer.seasonGoals||0};\n awards[year]=award;localStorage.setItem(tlAwardKey(),JSON.stringify(awards));return award;\n};\n"
if s.count(old)!=1: raise SystemExit('STOP: Award code differs from uploaded version, or update already installed. No changes made.')
updated=s.replace(old,new,1)
with tempfile.TemporaryDirectory() as d:
 for i,block in enumerate(re.findall(r'<script(?:\s[^>]*)?>(.*?)</script>',updated,re.S|re.I)):
  f=Path(d)/f'script_{i}.js';f.write_text(block,encoding='utf-8')
  check=subprocess.run(['node','--check',str(f)],capture_output=True,text=True)
  if check.returncode:raise SystemExit(f'STOP: JavaScript syntax error in script {i}:\n{check.stderr}')
backup=path.with_name('index-backup-before-player-award-'+datetime.now().strftime('%Y%m%d-%H%M%S')+'.html')
backup.write_text(s,encoding='utf-8')
path.write_text(updated,encoding='utf-8')
print('Backup:',backup.name)
print('Installed Player of the Year minimum 70% of competitive fixtures (league + cups).')
print('JavaScript syntax verified. Existing saved awards and careers unchanged.')
